	/** 
	 * jumpstart the process by instantiating2 Shipment
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		shipmentId = ShipmentService.getShipmentInstance()
		.createShipment( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		ShipmentService.getShipmentInstance()
				.createShipment( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.shipmentSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Shipment : " + successValue.getShipmentId());
							  if (successValue.getShipmentId().equals(shipmentId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfShipmentList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Shipment test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on shipment consumed")
					);
			subscriber.shipmentSubscribe( shipmentId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Shipment : " + successValue.getShipmentId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfShipmentList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on shipment for shipmentId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Shipment. 
	 */
	protected Shipment read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Shipment" );

		Shipment entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Shipment with primary key" );
		msg.append( shipmentId );
		
		ShipmentFetchOneSummary fetchOneSummary = new ShipmentFetchOneSummary( shipmentId );

		try {
			entity = ShipmentService.getShipmentInstance().getShipment( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Shipment " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Shipment.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Shipment." );

		StringBuilder msg = new StringBuilder( "Failed to update a Shipment : " );        
		Shipment entity = read();
		UpdateShipmentCommand command = generateUpdateCommand();
		command.setShipmentId(entity.getShipmentId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Shipment." );

			// for use later on...
			shipmentId = entity.getShipmentId();

			ShipmentService proxy = ShipmentService.getShipmentInstance();  

			proxy.updateShipment( command ).get();

			LOGGER.info( "-- Successfully saved Shipment - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + shipmentId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Shipment.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Shipment." );

		Shipment entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Shipment with id " + shipmentId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Shipment with id " + shipmentId );

			throw e;
		}

		try{
			ShipmentService.getShipmentInstance().delete( new DeleteShipmentCommand( entity.getShipmentId() ) ).get();
			LOGGER.info( "-- Successfully deleted Shipment with id " + shipmentId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Shipment with id " + shipmentId );

			throw e;
		}
	}

	/**
	 * get all Shipments.
	 */
	protected List<Shipment> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Shipments:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Shipment : " );        
		List<Shipment> collection  = new ArrayList<>();

		try {
			// call the static get method on the ShipmentService
			collection = ShipmentService.getShipmentInstance().getAllShipment();
			assertNotNull( collection, "An Empty collection of Shipment was incorrectly returned.");
			
			// Now print out the values
			Shipment entity = null;            
			Iterator<Shipment> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getShipmentId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

